<script setup lang="ts">
import PageNotice from '../components/PageNotice.vue';
import { scaledPopupProps } from '../utils/scaled-popup';
import { computed, onMounted, onBeforeUnmount, ref, watch } from 'vue'; import { useI18n } from 'vue-i18n'; import { useRoute, useRouter } from 'vue-router';
import { session } from '../services/api'; import { listEngagements,getEngagement,listThreads,listMessages,createInternalThread,sendProjectMessage,type Engagement,type EngagementDetail,type Thread,type Message } from '../services/operations'; import { formatJst } from '../services/audit'; import OperationsError from '../components/operations/OperationsError.vue';
const success=ref(false),successRun=ref(0);
const {t,te}=useI18n(), route=useRoute(),router=useRouter(); const projects=ref<Engagement[]>([]), detail=ref<EngagementDetail|null>(null), selected=ref(''),offset=ref(0),busy=ref(false),error=ref<unknown>(null),tab=ref('scope');
const threads=ref<Thread[]>([]),threadId=ref(''),messages=ref<Message[]>([]),messageOffset=ref(0),threadOffset=ref(0),threadHasNext=ref(false),messageHasNext=ref(false),message=ref(''),sendKey=ref(crypto.randomUUID()),dialog=ref<'send'|'internal'|null>(null),messageBusy=ref(false),messageError=ref<unknown>(null);
const agreement=computed(()=>detail.value?.agreements.at(-1)); const canMessage=computed(()=>session.account?.roles.some(r=>['administrator','operator'].includes(r))); const filteredThreads=computed(()=>threads.value.filter(item=>item.engagement_id===selected.value&&item.kind===(tab.value==='internal'?'internal':'customer_project')));
const status=(value:string)=>te(`ops.api.status.${value}`)?t(`ops.api.status.${value}`):value;
let detailRun=0,messageRun=0,threadRun=0,listRun=0;
async function loadList(){const n=++listRun;busy.value=true;error.value=null;try{const page=await listEngagements(offset.value);if(n!==listRun)return;projects.value=page.items;if(!selected.value)selected.value=offset.value===0&&typeof route.query.id==='string'?route.query.id:projects.value[0]?.id??'';if(selected.value)await selectProject();else detail.value=null}catch(e){if(n===listRun){error.value=e;projects.value=[];detail.value=null}}finally{if(n===listRun)busy.value=false}}
async function selectProject(){message.value='';sendKey.value=crypto.randomUUID();threadOffset.value=0;messageOffset.value=0;threads.value=[];messages.value=[];threadId.value='';++threadRun;++messageRun;if(selected.value){await loadDetail();if(['internal','customer'].includes(tab.value))await loadThreads()}}async function loadDetail(){const run=++detailRun;busy.value=true;error.value=null;detail.value=null;try{const result=await getEngagement(selected.value);if(run===detailRun)detail.value=result}catch(e){if(run===detailRun)error.value=e}finally{if(run===detailRun)busy.value=false}}
async function loadThreads(){if(!canMessage.value)return;const n=++threadRun;messageBusy.value=true;messageError.value=null;try{const result=await listThreads(threadOffset.value);if(n!==threadRun)return;threads.value=result.items;threadHasNext.value=result.items.length===100;threadId.value=filteredThreads.value[0]?.id??'';await loadMessages()}catch(e){if(n===threadRun){messageError.value=e;threads.value=[];messages.value=[]}}finally{if(n===threadRun)messageBusy.value=false}}async function loadMessages(){const run=++messageRun;messages.value=[];if(!threadId.value)return;messageBusy.value=true;messageError.value=null;try{const result=await listMessages(threadId.value,messageOffset.value);if(run===messageRun){messages.value=result.items;messageHasNext.value=result.items.length===50}}catch(e){if(run===messageRun)messageError.value=e}finally{if(run===messageRun)messageBusy.value=false}}
watch(tab,()=>{++threadRun;++messageRun;threads.value=[];messages.value=[];threadId.value='';message.value='';sendKey.value=crypto.randomUUID();messageOffset.value=0;if(['internal','customer'].includes(tab.value))loadThreads()});
watch(message,()=>{sendKey.value=crypto.randomUUID()});
async function confirm(){if(!detail.value)return;success.value=false;messageBusy.value=true;messageError.value=null;try{if(dialog.value==='internal'){const result=await createInternalThread(detail.value.engagement.request_id,selected.value);await loadThreads();threadId.value=result.id;await loadMessages()}else{await sendProjectMessage(threadId.value,message.value,sendKey.value);message.value='';await loadMessages()}dialog.value=null;success.value=true;++successRun.value}catch(e){messageError.value=e;dialog.value=null}finally{messageBusy.value=false}}
onMounted(loadList);onBeforeUnmount(()=>{++detailRun;++messageRun;++threadRun;++listRun});
</script>
<template><div class="page-stack module-page"><OperationsError :error="error"/><PageNotice v-if="success" :key="successRun" theme="success" :message="t('ops.api.saved')" @close="success=false"/><t-card :bordered="false" class="section-card"><div class="table-toolbar"><label>{{t('ops.api.selectProject')}}</label><t-select :popup-props="scaledPopupProps" v-model="selected" style="min-width:280px;flex:1" :options="[...projects,...(detail&&!projects.some(p=>p.id===detail?.engagement.id)?[detail.engagement]:[])].map(p=>({label:`${p.public_code} · ${status(p.status)}`,value:p.id}))" :disabled="busy" @change="selectProject"/><t-button variant="outline" :loading="busy" @click="loadList">{{t('ops.api.refresh')}}</t-button><t-button :disabled="offset===0||busy" variant="text" @click="offset-=20;selected='';loadList()">{{t('ops.api.previous')}}</t-button><t-button :disabled="projects.length<20||busy" variant="text" @click="offset+=20;selected='';loadList()">{{t('ops.api.next')}}</t-button></div><t-empty v-if="!busy&&!projects.length&&!detail&&!error" :description="t('ops.api.noProjects')"/></t-card>
<template v-if="detail"><PageNotice theme="info" :message="`${detail.engagement.public_code} · ${status(detail.engagement.status)}`"/><t-tabs v-model="tab"><t-tab-panel value="scope" :label="t('ops.api.scope')"/><t-tab-panel value="confirmations" :label="t('ops.api.confirmations')"/><t-tab-panel value="deliveries" :label="t('ops.project.deliveries')"/><t-tab-panel v-if="canMessage" value="customer" :label="t('ops.project.customer')"/><t-tab-panel v-if="canMessage" value="internal" :label="t('ops.api.internal')"/></t-tabs><div class="two-column module-scroll"><t-card :title="t('ops.project.progress')" :bordered="false" class="section-card"><template v-if="tab==='scope'"><div class="page-stack" v-if="agreement"><h2 class="record-title">{{agreement.scope.title}}</h2><section v-for="item in (['goal','included_scope','excluded_scope','deliverables','acceptance_criteria'] as const)" :key="item"><h3>{{t(`ops.api.${({goal:'goal',included_scope:'included',excluded_scope:'excluded',deliverables:'deliverables',acceptance_criteria:'criteria'})[item]}`)}}</h3><ul v-if="Array.isArray(agreement.scope[item])" class="scope-list"><li v-for="(value,index) in agreement.scope[item]" :key="index">{{value}}</li></ul><p v-else class="readable">{{agreement.scope[item]}}</p></section><h3>{{t('ops.api.terms')}} · v{{agreement.version}}</h3><p class="readable">{{agreement.terms}}</p></div><t-empty v-else :description="t('ops.api.none')"/></template><template v-if="tab==='confirmations'"><div class="page-stack"><t-empty v-if="!detail.confirmations.length" :description="t('ops.api.none')"/><article v-for="item in detail.confirmations" :key="`${item.agreement_version}-${item.party}`"><t-tag variant="light">v{{item.agreement_version}} · {{status(item.party)}}</t-tag><p class="mono">{{item.confirmed_by}}</p><p class="muted">{{formatJst(item.confirmed_at)}}</p></article></div></template><template v-if="tab==='deliveries'"><div class="page-stack"><t-empty v-if="!detail.deliveries.length" :description="t('ops.api.noDelivery')"/><article v-for="item in detail.deliveries" :key="item.id"><t-tag theme="primary" variant="light">v{{item.version}}</t-tag> · {{item.published?t('ops.api.published'):t('ops.api.unpublished')}}<p class="readable">{{item.note}}</p><p class="muted">{{formatJst(item.submitted_at)}}</p></article><t-button @click="router.push({path:'/delivery',query:{id:selected}})">{{t('ops.project.openDelivery')}}</t-button><h3>{{t('ops.api.acceptance')}}</h3><t-empty v-if="!detail.acceptances.length" :description="t('ops.api.none')"/><article v-for="item in detail.acceptances" :key="item.id"><strong>v{{item.delivery_version}} · {{status(item.decision)}}</strong><p class="readable">{{item.feedback}}</p><p class="muted">{{formatJst(item.decided_at)}}</p></article></div></template>
<div v-if="['customer','internal'].includes(tab)&&canMessage" class="page-stack"><OperationsError :error="messageError"/><PageNotice :notification="tab==='customer'" :theme="tab==='internal'?'warning':'info'" :message="t(tab==='internal'?'ops.project.noteBoundary':'ops.api.sendConfirm')"/><PageNotice notification theme="info" :message="t('ops.api.pageFilter')"/><t-space break-line><t-select :popup-props="scaledPopupProps" v-model="threadId" style="width:280px" :options="filteredThreads.map(item=>({label:item.id,value:item.id}))" @change="messageOffset=0;loadMessages()"/><t-button :disabled="threadOffset===0||messageBusy" @click="threadOffset-=100;loadThreads()">{{t('ops.api.previous')}}</t-button><t-button :disabled="!threadHasNext||messageBusy" @click="threadOffset+=100;loadThreads()">{{t('ops.api.next')}}</t-button></t-space><t-empty v-if="!threadId&&!messageBusy" :description="t('ops.api.threadEmpty')"/><t-button v-if="tab==='internal'&&!filteredThreads.length" :disabled="messageBusy" @click="dialog='internal'">{{t('ops.api.createInternal')}}</t-button><template v-if="threadId"><article v-for="item in messages" :key="item.id" class="message-card"><p class="muted">{{item.author_name}} · {{formatJst(item.sent_at)}}</p><p class="readable">{{item.body}}</p></article><t-space><t-button :disabled="messageOffset===0||messageBusy" variant="text" @click="messageOffset-=50;loadMessages()">{{t('ops.api.previous')}}</t-button><t-button :disabled="!messageHasNext||messageBusy" variant="text" @click="messageOffset+=50;loadMessages()">{{t('ops.api.next')}}</t-button></t-space><label>{{t('ops.api.message')}}</label><t-textarea v-model="message" :maxlength="4000" :autosize="{minRows:3,maxRows:8}"/><t-button :disabled="!message.trim()||messageBusy" @click="dialog='send'">{{t('ops.api.send')}}</t-button></template></div></t-card>
<t-card :title="t('ops.project.info')" :bordered="false" class="section-card"><t-descriptions :column="1"><t-descriptions-item :label="t('ops.api.projectId')"><span class="mono wrap">{{detail.engagement.id}}</span></t-descriptions-item><t-descriptions-item :label="t('ops.api.customer')"><span class="mono wrap">{{detail.engagement.customer_id}}</span></t-descriptions-item><t-descriptions-item :label="t('ops.api.provider')"><span class="mono wrap">{{detail.engagement.provider_id||'—'}}</span></t-descriptions-item><t-descriptions-item :label="t('ops.api.rowVersion')">{{detail.engagement.row_version}}</t-descriptions-item><t-descriptions-item :label="t('ops.api.price')">{{agreement?.quoted_amount==null?'—':`${agreement.quoted_amount.toLocaleString()} JPY`}}</t-descriptions-item><t-descriptions-item :label="t('ops.api.due')">{{formatJst(agreement?.due_at)}}</t-descriptions-item></t-descriptions><PageNotice notification theme="info" :message="t('ops.project.boundary')"/></t-card></div></template>
<t-dialog :visible="dialog!==null" :header="t('ops.api.confirmAction')" :confirm-btn="{content:t('ops.confirm'),loading:messageBusy}" :cancel-btn="t('ops.cancel')" @close="dialog=null" @confirm="confirm"><PageNotice inline theme="info" :message="t(dialog==='internal'?'ops.api.createInternalHint':'ops.api.sendConfirm')"/><p v-if="dialog==='send'" class="readable">{{message}}</p></t-dialog></div></template>
<style scoped>h3{font-size:14px;margin-bottom:10px}.wrap{overflow-wrap:anywhere}.message-card{padding:16px;background:var(--td-bg-color-secondarycontainer);border-radius:var(--td-radius-default)}</style>



